typedef struct {
    int data, left, right;
} Node;

Node tree[N] = {
    {3, 1, 2}, {5, 3, 4}, {1, -1, -1},
    {6, -1, -1}, {2, -1, -1}
};

// 找从根到目标结点的路径，成功返回 1
int getPath(int u, int target, int path[], int *len) {
    if (u == -1) return 0;

    path[(*len)++] = u;
    if (u == target) return 1;

    if (getPath(tree[u].left, target, path, len) ||
        getPath(tree[u].right, target, path, len))
        return 1;

    (*len)--;  // 此路不通，回溯
    return 0;
}

int main(void) {
    int p = 3, q = 4; // 结点值分别为 6、2
    int a[N], b[N], na = 0, nb = 0;
    getPath(0, p, a, &na);
    getPath(0, q, b, &nb);

    int ans = -1;
    for (int i = 0; i < na && i < nb; i++) {
        if (a[i] != b[i]) break;
        ans = a[i]; // 最后一个相同的祖先
    }

    printf("%d\n", tree[ans].data); // 5
    return 0;
}

