#include <stdio.h>

#define N 5

// 用数组存储二叉树：-1 表示没有孩子
typedef struct {
    int data, left, right;
} Node;

Node tree[N] = {
    {3, 1, 2}, {5, 3, 4}, {1, -1, -1},
    {6, -1, -1}, {2, -1, -1}
};

// 后序思想：左右子树各返回找到的目标结点
int lca(int u, int p, int q) {
    if (u == -1 || u == p || u == q)
        return u;

    int left = lca(tree[u].left, p, q);
    int right = lca(tree[u].right, p, q);

    if (left != -1 && right != -1)
        return u; // 两边各有一个目标，当前结点是最近公共祖先

    return left != -1 ? left : right;
}

int main(void) {
    int p = 3, q = 4; // 6 与 2
    int ans = lca(0, p, q);
    printf("%d\n", tree[ans].data); // 5
    return 0;
}

